// Message is any FAST message decoded by Router in this package.
type Message interface{ isFASTMessage() }

// Router decodes a stream of FAST messages, dispatching on the template id. It
// is reusable; its template-id dictionary and per-template decoders persist
// across messages.
//
// Decode returns a pointer into a per-template struct that Decode REUSES on the
// next call for the same template. The returned Message is therefore only valid
// until the next Decode call: to retain a message, type-assert it and copy the
// value before calling Decode again. This reuse is what keeps decoding
// allocation-free.
type Router struct {
	pmap    []byte
	tidSlot fastcore.UintSlot

	// ResetID is the template id of the feed's FAST reset control message
	// (e.g. 120 for T7 MDI/EMDI). When non-zero and a message with this id is
	// decoded, Router resets all dictionaries and Decode returns (nil, nil).
	// Leave it 0 to treat every id as a regular template.
	ResetID                      uint32
	MDPacketHeaderDec            MDPacketHeaderDecoder
	MDPacketHeaderMsg            MDPacketHeader
	ProductStateChangeDec        ProductStateChangeDecoder
	ProductStateChangeMsg        ProductStateChange
	MassInstrumentStateChangeDec MassInstrumentStateChangeDecoder
	MassInstrumentStateChangeMsg MassInstrumentStateChange
	InstrumentStateChangeDec     InstrumentStateChangeDecoder
	InstrumentStateChangeMsg     InstrumentStateChange
	DepthIncrementalDec          DepthIncrementalDecoder
	DepthIncrementalMsg          DepthIncremental
	ComplexInstrumentUpdateDec   ComplexInstrumentUpdateDecoder
	ComplexInstrumentUpdateMsg   ComplexInstrumentUpdate
	QuoteRequestDec              QuoteRequestDecoder
	QuoteRequestMsg              QuoteRequest
	CrossRequestDec              CrossRequestDecoder
	CrossRequestMsg              CrossRequest
	DepthSnapshotDec             DepthSnapshotDecoder
	DepthSnapshotMsg             DepthSnapshot
	IndexStatsDec                IndexStatsDecoder
	IndexStatsMsg                IndexStats
	TopOfBookImpliedDec          TopOfBookImpliedDecoder
	TopOfBookImpliedMsg          TopOfBookImplied
	FlexibleInstrumentUpdateDec  FlexibleInstrumentUpdateDecoder
	FlexibleInstrumentUpdateMsg  FlexibleInstrumentUpdate
}

// Reset returns every dictionary (the template-id dictionary and all per-
// template decoders) to the undefined state.
func (rt *Router) Reset() {
	rt.tidSlot.Reset()
	rt.MDPacketHeaderDec.Reset()
	rt.ProductStateChangeDec.Reset()
	rt.MassInstrumentStateChangeDec.Reset()
	rt.InstrumentStateChangeDec.Reset()
	rt.DepthIncrementalDec.Reset()
	rt.ComplexInstrumentUpdateDec.Reset()
	rt.QuoteRequestDec.Reset()
	rt.CrossRequestDec.Reset()
	rt.DepthSnapshotDec.Reset()
	rt.IndexStatsDec.Reset()
	rt.TopOfBookImpliedDec.Reset()
	rt.FlexibleInstrumentUpdateDec.Reset()
}

// Decode reads and decodes the next message from r. On the FAST reset control
// message (see ResetID) it resets all dictionaries and returns (nil, nil); the
// caller should treat a nil Message as a consumed control message and continue.
func (rt *Router) Decode(r *fastcore.Reader) (Message, error) {
	pm, err := r.ReadPMAP(rt.pmap)
	if err != nil {
		return nil, err
	}
	rt.pmap = pm.Buffer()
	tid, _, err := fastcore.DecodeUint(r, &pm, fastcore.OpCopy, fastcore.W32, false, false, 0, &rt.tidSlot)
	if err != nil {
		return nil, err
	}
	if rt.ResetID != 0 && tid == uint64(rt.ResetID) {
		rt.Reset()
		return nil, nil
	}
	switch tid {
	case 65:
		if err := rt.MDPacketHeaderDec.decodeMDPacketHeader(r, &pm, &rt.MDPacketHeaderMsg); err != nil {
			return nil, err
		}
		return &rt.MDPacketHeaderMsg, nil
	case 108:
		if err := rt.ProductStateChangeDec.decodeProductStateChange(r, &pm, &rt.ProductStateChangeMsg); err != nil {
			return nil, err
		}
		return &rt.ProductStateChangeMsg, nil
	case 104:
		if err := rt.MassInstrumentStateChangeDec.decodeMassInstrumentStateChange(r, &pm, &rt.MassInstrumentStateChangeMsg); err != nil {
			return nil, err
		}
		return &rt.MassInstrumentStateChangeMsg, nil
	case 103:
		if err := rt.InstrumentStateChangeDec.decodeInstrumentStateChange(r, &pm, &rt.InstrumentStateChangeMsg); err != nil {
			return nil, err
		}
		return &rt.InstrumentStateChangeMsg, nil
	case 102:
		if err := rt.DepthIncrementalDec.decodeDepthIncremental(r, &pm, &rt.DepthIncrementalMsg); err != nil {
			return nil, err
		}
		return &rt.DepthIncrementalMsg, nil
	case 105:
		if err := rt.ComplexInstrumentUpdateDec.decodeComplexInstrumentUpdate(r, &pm, &rt.ComplexInstrumentUpdateMsg); err != nil {
			return nil, err
		}
		return &rt.ComplexInstrumentUpdateMsg, nil
	case 106:
		if err := rt.QuoteRequestDec.decodeQuoteRequest(r, &pm, &rt.QuoteRequestMsg); err != nil {
			return nil, err
		}
		return &rt.QuoteRequestMsg, nil
	case 107:
		if err := rt.CrossRequestDec.decodeCrossRequest(r, &pm, &rt.CrossRequestMsg); err != nil {
			return nil, err
		}
		return &rt.CrossRequestMsg, nil
	case 101:
		if err := rt.DepthSnapshotDec.decodeDepthSnapshot(r, &pm, &rt.DepthSnapshotMsg); err != nil {
			return nil, err
		}
		return &rt.DepthSnapshotMsg, nil
	case 51:
		if err := rt.IndexStatsDec.decodeIndexStats(r, &pm, &rt.IndexStatsMsg); err != nil {
			return nil, err
		}
		return &rt.IndexStatsMsg, nil
	case 513:
		if err := rt.TopOfBookImpliedDec.decodeTopOfBookImplied(r, &pm, &rt.TopOfBookImpliedMsg); err != nil {
			return nil, err
		}
		return &rt.TopOfBookImpliedMsg, nil
	case 110:
		if err := rt.FlexibleInstrumentUpdateDec.decodeFlexibleInstrumentUpdate(r, &pm, &rt.FlexibleInstrumentUpdateMsg); err != nil {
			return nil, err
		}
		return &rt.FlexibleInstrumentUpdateMsg, nil
	default:
		return nil, fmt.Errorf("fast: unknown template id %d", tid)
	}
}
